import axios from 'axios';

const API_CARS = 'http://localhost:8085/api/cars';
const API_RENTALS = 'http://localhost:8085/api/rentals';
const API_CUSTOMERS = 'http://localhost:8085/api/customers';
const API_PAYMENTS = 'http://localhost:8085/api/payments';
const API_BRANCHES = 'http://localhost:8085/api/branches';

const api = {

    findAllCars: function() {
        return axios.get(API_CARS);
    },

    findCarById: function(id) {
        return axios.get(API_CARS + '/' + id);
    },

    saveCar: function(item) {
        return axios.post(API_CARS, item);
    },

    updateCar: function(id, item) {
        return axios.put(API_CARS + '/' + id, item);
    },

    deleteCar: function(id) {
        return axios.delete(API_CARS + '/' + id);
    },

    rentCar: function(data) {
        return axios.post(API_RENTALS, data);
    },

    findAllRentals: function() {
        return axios.get(API_RENTALS);
    },

    findRentalById: function(id) {
        return axios.get(API_RENTALS + '/' + id);
    },

    updateRental: function(id, item) {
        return axios.put(API_RENTALS + '/' + id, item);
    },

    deleteRental: function(id) {
        return axios.delete(API_RENTALS + '/' + id);
    },

    findAllCustomers: function() {
        return axios.get(API_CUSTOMERS);
    },

    findCustomerById: function(id) {
        return axios.get(API_CUSTOMERS + '/' + id);
    },

    saveCustomer: function(item) {
        return axios.post(API_CUSTOMERS, item);
    },

    updateCustomer: function(id, item) {
        return axios.put(API_CUSTOMERS + '/' + id, item);
    },

    deleteCustomer: function(id) {
        return axios.delete(API_CUSTOMERS + '/' + id);
    },

    findAllPayments: function() {
        return axios.get(API_PAYMENTS);
    },

    findPaymentById: function(id) {
        return axios.get(API_PAYMENTS + '/' + id);
    },

    savePayment: function(item) {
        return axios.post(API_PAYMENTS, item);
    },

    updatePayment: function(id, item) {
        return axios.put(API_PAYMENTS + '/' + id, item);
    },

    deletePayment: function(id) {
        return axios.delete(API_PAYMENTS + '/' + id);
    },

    findAllBranches: function() {
        return axios.get(API_BRANCHES);
    },

    findBranchById: function(id) {
        return axios.get(API_BRANCHES + '/' + id);
    },

    saveBranch: function(item) {
        return axios.post(API_BRANCHES, item);
    },

    updateBranch: function(id, item) {
        return axios.put(API_BRANCHES + '/' + id, item);
    },

    deleteBranch: function(id) {
        return axios.delete(API_BRANCHES + '/' + id);
    }

};

export default api;
